<?php
require __DIR__ . '/../../config/database.php';
require __DIR__ . '/../../includes/auth-check.php';
require_admin();
$volunteerId = (int) ($_GET['volunteer_id'] ?? $_POST['volunteer_id'] ?? 0); $error = '';
$statement = mysqli_prepare($conn, 'SELECT v.*, u.full_name, u.email, u.tp_number, u.intake_code, u.academic_program FROM volunteer_profiles v JOIN users u ON u.user_id = v.user_id WHERE v.volunteer_id = ? LIMIT 1'); mysqli_stmt_bind_param($statement, 'i', $volunteerId); mysqli_stmt_execute($statement); $application = mysqli_fetch_assoc(mysqli_stmt_get_result($statement)); mysqli_stmt_close($statement);
if (!$application) { http_response_code(404); exit('Application not found.'); }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $status = $_POST['approval_status'] ?? ''; if (!in_array($status, ['Approved', 'Rejected'], true)) { $error = 'Choose Approved or Rejected.'; } else { $adminId = (int) current_user()['user_id']; $statement = mysqli_prepare($conn, "UPDATE volunteer_profiles SET approval_status = ?, approved_by = ?, approved_at = CASE WHEN ? = 'Approved' THEN NOW() ELSE NULL END WHERE volunteer_id = ?"); mysqli_stmt_bind_param($statement, 'sisi', $status, $adminId, $status, $volunteerId); mysqli_stmt_execute($statement); mysqli_stmt_close($statement); header('Location: volunteer-applications.php'); exit; } }
require __DIR__ . '/../../includes/header.php';
?>
<section class="section"><div class="container"><a href="volunteer-applications.php">&larr; Back to applications</a><h1>Volunteer Application</h1><?php if ($error): ?><div class="alert alert-danger"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><div class="card"><p><strong>Name:</strong> <?= htmlspecialchars($application['full_name'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>Email:</strong> <?= htmlspecialchars($application['email'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>TP number:</strong> <?= htmlspecialchars($application['tp_number'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>Intake / programme:</strong> <?= htmlspecialchars($application['intake_code'] ?? '', ENT_QUOTES, 'UTF-8') ?> / <?= htmlspecialchars($application['academic_program'] ?? '', ENT_QUOTES, 'UTF-8') ?></p><p><strong>Current status:</strong> <?= htmlspecialchars($application['approval_status'], ENT_QUOTES, 'UTF-8') ?></p><h2>Skills and experience</h2><p><?= nl2br(htmlspecialchars($application['skills_description'], ENT_QUOTES, 'UTF-8')) ?></p><form method="post"><input type="hidden" name="volunteer_id" value="<?= $volunteerId ?>"><button class="btn btn-primary" name="approval_status" value="Approved" type="submit">Approve</button> <button class="btn btn-outline-primary" name="approval_status" value="Rejected" type="submit">Reject</button></form></div></div></section>
<?php require __DIR__ . '/../../includes/footer.php'; ?>
